import pytest


def age_at(born: int, now: int) -> int:
    """Whole years from birth year `born` to current year `now`.

    The current year is supplied by the caller; this function never reads the clock.
    Raises ValueError if `now` is earlier than `born`.
    """
    if now < born:
        raise ValueError(f"now ({now}) is earlier than born ({born})")
    return now - born


def test_age_at_whole_years() -> None:
    assert age_at(1990, 2024) == 34


def test_age_at_same_year_is_zero() -> None:
    assert age_at(2000, 2000) == 0


def test_age_at_one_year_apart() -> None:
    assert age_at(1999, 2000) == 1


def test_age_at_rejects_now_before_born() -> None:
    with pytest.raises(ValueError):
        age_at(2001, 2000)
